<template><section class="view on"><PageHead title="社区评论" sub="隐藏评论不会改变帖子审核状态"><div class="toolbar"><button v-for="s in states" :key="s.value" class="chip" :class="{on:status===s.value}" type="button" @click="change(s.value)">{{s.label}}</button></div></PageHead><div class="sheet"><table><thead><tr><th>评论</th><th>帖子</th><th>作者</th><th>状态</th><th>时间</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.commentId"><td>{{row.content}}</td><td>#{{row.postId}}</td><td>{{row.author?.nickname || '—'}}</td><td><span class="pill" :class="row.status === 'published' ? 'ok' : 'bad'">{{row.status}}</span></td><td>{{row.createdAt}}</td><td><button class="linkish" type="button" @click="setStatus(row,row.status === 'published' ? 'hidden' : 'published')">{{row.status === 'published' ? '隐藏' : '恢复'}}</button></td></tr><tr v-if="!loading && !rows.length"><td colspan="6"><div class="empty">暂无评论</div></td></tr></tbody></table></div></section></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import PageHead from '@/components/kitchen/PageHead.vue';import {listAdminComments,updateAdminCommentStatus,type AdminComment} from '@/api/social';import {toast} from '@/utils/toast';const rows=ref<AdminComment[]>([]),loading=ref(false),status=ref('');const states=[{value:'',label:'全部'},{value:'published',label:'已发布'},{value:'hidden',label:'已隐藏'}];async function load(){loading.value=true;try{rows.value=(await listAdminComments({status:status.value||undefined,page:1,pageSize:100})).data?.list||[]}finally{loading.value=false}}function change(v:string){status.value=v;load()}async function setStatus(row:AdminComment,toStatus:string){try{await updateAdminCommentStatus(row.commentId,{toStatus,reason:'运营处理'});toast('评论状态已更新');load()}catch {}}onMounted(load)
</script>
